import fs from 'node:fs/promises';
import path from 'node:path';

const UUID = '[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}';
const KEY_PATTERN = new RegExp(`^${UUID}/${UUID}\\.jpg$`);
const UUID_PATTERN = new RegExp(`^${UUID}$`);

/**
 * Stores processed photos on disk as `<photosDir>/<plantId>/<photoId>.jpg`.
 * Keys are generated by the server and re-validated before any filesystem
 * access, so request input can never point outside the photos directory.
 */
export function createPhotoStore(photosDir: string) {
  const root = path.resolve(photosDir);

  function resolveKey(key: string): string {
    if (!KEY_PATTERN.test(key)) throw new Error(`Invalid photo storage key: ${key}`);
    const fullPath = path.resolve(root, key);
    if (!fullPath.startsWith(root + path.sep)) throw new Error(`Photo key escapes storage: ${key}`);
    return fullPath;
  }

  return {
    keyFor(plantId: string, photoId: string): string {
      return `${plantId}/${photoId}.jpg`;
    },

    resolve: resolveKey,

    /** Writes atomically (temp file + rename) so a crash never leaves a half-written image. */
    async save(key: string, data: Buffer): Promise<void> {
      const target = resolveKey(key);
      await fs.mkdir(path.dirname(target), { recursive: true });
      const temp = `${target}.${process.pid}.tmp`;
      await fs.writeFile(temp, data);
      await fs.rename(temp, target);
    },

    read(key: string): Promise<Buffer> {
      return fs.readFile(resolveKey(key));
    },

    /** Deletes a photo file; a file that is already gone is not an error. */
    async remove(key: string): Promise<void> {
      await fs.rm(resolveKey(key), { force: true });
    },

    /** Deletes the whole directory of a plant's photos. */
    async removePlantDir(plantId: string): Promise<void> {
      if (!UUID_PATTERN.test(plantId)) throw new Error(`Invalid plant id: ${plantId}`);
      await fs.rm(path.join(root, plantId), { recursive: true, force: true });
    },
  };
}

export type PhotoStore = ReturnType<typeof createPhotoStore>;
